namespace Honua.Db.Postgres.Features.Raster;

/// <summary>Admits only tiles generated by the current sampler with unchanged payload bytes.</summary>
internal static class RasterTileProvenanceSql
{
    // Older writers have no corrected-sampler provenance. Migration defaults keep their
    // inserts untrusted; payload hashing detects their overwrites of a versioned row.
    internal const int LegacyRendererVersion = 0;

    // The CASE keeps unknown legacy bodies out of the hashing path. Version alone is
    // insufficient: an already-running old writer can overwrite tile_data on a new row.
    internal const string AdmissionPredicate = """
        CASE WHEN renderer_version = @rendererVersion
                  AND octet_length(renderer_payload_sha256) = 32
             THEN renderer_payload_sha256 = sha256(tile_data)
             ELSE FALSE END
        """;
}
